package com.smartdairy.controller;
import com.smartdairy.entity.Delivery; import com.smartdairy.service.DeliveryService; import jakarta.servlet.*; import jakarta.servlet.http.*; import java.io.IOException; import java.sql.Date;
public class DeliveryController extends HttpServlet{private final DeliveryService service=new DeliveryService(); protected void doPost(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{try{Delivery d=new Delivery();d.setOrderId(Integer.parseInt(r.getParameter("order_id")));d.setDeliveryPerson(r.getParameter("delivery_person"));d.setMobile(r.getParameter("mobile"));d.setVehicleNumber(r.getParameter("vehicle_number"));d.setDeliveryDate(Date.valueOf(r.getParameter("delivery_date")));d.setRoute(r.getParameter("route"));d.setStatus(r.getParameter("status"));d.setRemarks(r.getParameter("remarks"));service.save(d);s.sendRedirect("delivery.jsp?success=true");}catch(Exception e){s.sendRedirect("delivery.jsp?error=true");}}}
